def do_algebra(opers, nums):

    def apply_op(a1,a2,o):
        """Apply an operation on two values"""
        ops = {'+':add,'*':mul,'//':floordiv,'**':pow}
        op_func = ops[o]
        result = op_func(a1,a2)
        return result

