from typing import List
def count_consonants(word: str) -> int:
    """Helper function to count the number of consonants in a given word"""
    vowels = set('aeiouAEIOU')
    count = 0
    for char in word:
        if char.isalpha() and char not in vowels:
            count += 1
    return count
def select_words(s: str, n: int) -> List[str]:
    """Selects words from the input string s that have exactly n consonants"""
    words = s.split()
    result = []

    for word in words:
        if count_consonants(word) == n:
            result.append(word)

    return result

