from collections import Counter
def count_occurrences(lst):
    """Helper function to count occurrences of each element in the list."""
    counter = Counter(lst)
    single_count = 0  # To count occurrences of single unique element

    for count in counter.values():
        if count == 1:
            single_count += 1

        elif count > 1:
            return False  # Found an occurrence of an element appearing twice or three times

        elif count != 1 and count != 2:
            raise ValueError("Unsupported count of occurrences")

    return single_count  # Check if there's only one unique element
def is_sorted(lst):
    """Main function to determine the sort order of the list"""

    count = count_occurrences(lst)

    if count != 1:
        raise ValueError("Unsupported count of occurrences")

    n = len(lst)

    i = 1  # Initialize index starting from the second element

    while i < n:
        if lst[i] < lst[i - 1]:
            return False  # Found an element that's smaller than the one before it

        i += 1

    return True

from typing import List
def get_closest_vowel(word: str) -> str:
    vowels = set('AEIOUY')  # Set of all vowels in both lower and upper case

    def find_previous_consonant(index: int) -> int:
        while index > 0 and word[index] in vowels:
            index -= 1
        return index

    def find_next_consonant(index: int) -> int:
        while index < len(word) and word[index] in vowels:
            index += 1
        return index

    for i in range(len(word), 1, -1):  # Traverse the string from right to left
        prev = find_previous_consonant(i)
        next = find_next_consonant(i)
        if prev != i and prev != 0 and next != i and next != 1:
            return word[prev]

    return ""

