from typing import List
def triples_sum_to_zero(nums: List[int]) -> bool:
    nums.sort()  # Sort the list first to facilitate the two-pointer technique

    n = len(nums)

    for i in range(n-2):  # Traverse the list till the third last element

        j = i + 1  # Initialize the second pointer starting from the element right after the current one

        k = n - 1  # Initialize the third pointer starting from the end of the list

        while j < k:

            current_sum = nums[i] + nums[j] + nums[k]

            if current_sum == 0:

                return True  # Found three numbers whose sum is 0; return True

            elif current_sum < 0:

                j += 1  # Increase the second pointer because the current number (at index j) is too small

            else:

                k -= 1  # Decrease the third pointer because the current number (at index k) is too large

    return False  # No three numbers found whose sum is 0; return False

def get_max_triples(n):

    # Initialize the array based on the formula provided in the problem statement
    array = list(map(lambda i : i*i-i+1, range(1,n+1)))

    count = 0  # Variable used to count the number of valid triples

    # Check all possible pairs of indices (i, j)
    for i in range(len(array)):
        for j in range(i+1,len(array)):

            # Calculate the sum of the three values from the array at positions i, j and k (where i < j < k)
            s = array[i]+array[j]+array[min(j,i+1)]

            # Check if the sum of the three values is divisible by 3 and count it as valid
            if s % 3 == 0:
                count+=1

    return count

def is_nested(string):
    stack = []

    # Traverse the string character by character
    for char in string:
        if char == '[':
            stack.append(char)
        elif char == ']':
            if stack:
                stack.pop()  # Remove the last element from the stack (indicating an open square bracket)

                # Check if the stack isn't empty after processing the current character,
                # indicating that there's been an open square bracket that wasn't closed,
                # thus confirming the presence of nested square brackets.
                if stack:
                    return True

    # If no nested sequence found or stack still has elements,
    # it means there's no nested sequence of square brackets in the string.
    return False

