    # Check if the string length is 1 or 2 because no rotation will change it back to the same string in these cases
    if n <= 1:
        return 1

    count = 1  # Initialize rotation counter

    while count * n != n:
        string = string[1:] + string[0]  # Perform one rotation on the string
