def reverse_vowels(text):
    vowels = set('AEIOUY')  # Set of vowels including both upper and lower case letters

    i = 0  # Initialize the starting index of the string
    j = len(text) - 1  # Initialize the ending index of the string

    while i < j:
        while i < j and text[i] not in vowels:
            i += 1  # Increment the starting index while the current character is not a vowel

        while i < j and text[j] not in vowels:
            j -= 1  # Decrement the ending index while the current character is not a vowel

        if i != j:
            temp = text[i]
            text[i] = text[j]
            text[j] = temp  # Swap the characters

        i += 1  # Increment the starting index
        j -= 1  # Decrement the ending index

    return text  # Return the reversed string

